import{_ as r,C as d,o,c as s,j as a,a as i,E as n,a2 as h}from"./chunks/framework.B-bxTAy7.js";const f=JSON.parse('{"title":"怎么用这个站","description":"三条阅读路径、页面标注的含义、搜索与前置知识抽屉的用法，以及暗色模式和打印。","frontmatter":{"title":"怎么用这个站","description":"三条阅读路径、页面标注的含义、搜索与前置知识抽屉的用法，以及暗色模式和打印。"},"headers":[],"relativePath":"guide/start.md","filePath":"guide/start.md","lastUpdated":1792416913000}'),l={name:"guide/start.md"};function c(p,t,b,m,u,_){const e=d("Meta");return o(),s("div",null,[t[0]||(t[0]=a("h1",{id:"怎么用这个站",tabindex:"-1"},[i("怎么用这个站 "),a("a",{class:"header-anchor",href:"#怎么用这个站","aria-label":'Permalink to "怎么用这个站"'},"​")],-1)),n(e,{time:"4 min",level:"指南",note:"三条路径 + 四个交互约定，读完就不用再猜了"}),t[1]||(t[1]=h('<h2 id="选一条路径" tabindex="-1">选一条路径 <a class="header-anchor" href="#选一条路径" aria-label="Permalink to &quot;选一条路径&quot;">​</a></h2><p>不知道从哪开始？先看<a href="./../map">学习地图</a>：它把四门课、项目专题和实验串成一条从看懂电路到做出东西的路线，再回来挑下面的一条。</p><table tabindex="0"><thead><tr><th>你的情况</th><th>走这条</th><th>大概耗时</th></tr></thead><tbody><tr><td>第一次学，要能做题</td><td>课程主页 → 从 01 顺序读 → 每章做演示、做例题</td><td>电工学约 12 h</td></tr><tr><td>考前一周，只求骨架</td><td>每章「结论先行」+「考点速记」+ <a href="./../shared/cheatsheet">公式速查表</a></td><td>约 6.5 h</td></tr><tr><td>学过但忘了，想补漏</td><td>先看<a href="./../ee/graph">依赖图谱</a>，从卡住的那章读起</td><td>按需</td></tr></tbody></table><h2 id="三个交互约定" tabindex="-1">三个交互约定 <a class="header-anchor" href="#三个交互约定" aria-label="Permalink to &quot;三个交互约定&quot;">​</a></h2><p><strong>1. 前置知识胶囊</strong> 正文里像 <span class="demo-chip">💡 戴维南定理</span> 这样的小胶囊，点一下从右侧滑出卡片：先是一句话摘要，下面是完整卡片。按 <kbd>Esc</kbd> 或点「继续阅读」回到原处——<strong>页面滚动位置不会丢</strong>。</p><p><strong>2. 演示（DemoBox）</strong> 带「交互演示」标签的框里，滑块、按钮都可以动，图形会实时重算。建议先自己拖到极端值（比如把负载拖到 0、把频率拖到谐振点），再看正文的解释——比先读结论印象深。</p><p><strong>3. 图解（FigBox）</strong> 图解框下面是图注，写的是「这张图想让你看见什么」。公式和图对不上时，以图为准，然后回来改公式。</p><p><strong>4. 搜索</strong> 右上角搜索框或 <kbd>Ctrl</kbd> + <kbd>K</kbd>。中文按 2-gram 分词，输入「戴维南」「转差率」「卡诺图」都能命中；支持拼音首字母以外的模糊匹配，但<strong>不支持拼音</strong>。</p><h2 id="页面上的标注" tabindex="-1">页面上的标注 <a class="header-anchor" href="#页面上的标注" aria-label="Permalink to &quot;页面上的标注&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标注</th><th>含义</th></tr></thead><tbody><tr><td>🔴 核心</td><td>必读，考试与后续章节都依赖</td></tr><tr><td>🟡 了解</td><td>看结论和公式即可，推导可跳</td></tr><tr><td>🟢 可跳过</td><td>与其它课程重叠或偏专题，学过直接跳</td></tr><tr><td>⏱ 约 30 min</td><td>按「读结论 + 做演示 + 看例题」估的时间，不含自己做题</td></tr><tr><td>本页更新于 …</td><td>来自 git 提交时间；只改过格式也会更新</td></tr></tbody></table><h2 id="外观与打印" tabindex="-1">外观与打印 <a class="header-anchor" href="#外观与打印" aria-label="Permalink to &quot;外观与打印&quot;">​</a></h2><ul><li>右上角的 ☀/🌙 切换浅色/深色；默认跟随系统。</li><li>公式、表格、演示都适配了窄屏；侧边栏在手机上收进左上角「课程目录」。</li><li>打印页面时会自动隐藏导航与侧边栏，表格与公式保留——<a href="./../shared/cheatsheet">公式速查表</a>可以直接打成 A4。</li></ul><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li>公式渲染错位、图不显示：翻到页面底部看是否有更新提示，或在<a href="./about">关于与版权</a>里找反馈方式。</li><li>内容有错：请指出章节与那句原话，比「感觉不对」有用得多。</li></ul>',14))])}const k=r(l,[["render",c]]);export{f as __pageData,k as default};
